<p class="eyebrow">Financial operations</p><h1>Immutable ledger</h1><section class="card"><h2>Manual adjustment</h2><form method="post" action="<?= e(route('admin.transactions.adjust')) ?>" class="form-grid"><?= app('csrf')->input() ?><label>User ID<input name="user_id" inputmode="numeric" required></label><label>Amount<input name="amount" inputmode="decimal" required></label><label>Direction<select name="direction"><option value="CREDIT">Credit</option><option value="DEBIT">Debit</option></select></label><label>Reason<input name="reason" required></label><button class="button">Record adjustment</button></form></section><div class="table-wrap"><table><thead><tr><th>Reference</th><th>User</th><th>Type</th><th>Direction</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?= e($t['reference']) ?></td><td><?= e($t['email']) ?></td><td><?= e($t['transaction_type']) ?></td><td><?= e($t['direction']) ?></td><td><?= money((int)$t['amount_minor']) ?></td><td><?= e($t['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div>
